    release() { noiseBurst(0.12, 0.25, 3000); tone(300, 0.08, 'square', 0.08, 900); },
    pop(balloon) {
      const f = balloon.freq;
      tone(f, 0.12, 'triangle', 0.3, f * 0.5);
      tone(f * 2, 0.06, 'sine', 0.15, f * 1.5);
      noiseBurst(0.05, 0.2, 6000);
    },
    whiff() { tone(400, 0.15, 'sawtooth', 0.06, 120); },
    point() { tone(660, 0.1, 'square', 0.12, 990); },
    over() { tone(400, 0.4, 'sawtooth', 0.2, 60); tone(200, 0.6, 'triangle', 0.15, 40); },
    start() { tone(440, 0.12, 'square', 0.15, 660); setTimeout(() => tone(660, 0.15, 'square', 0.15, 880), 100); }
  };

